<?php
define('APP_INIT',true); $pageTitle='My Subscription'; $activeMenu='subscription'; require_once __DIR__.'/../../includes/header.php';
$db=Database::getConnection();$tenant=TenantContext::id();$sub=SubscriptionService::activeSubscription($db,$tenant);$map=['companies'=>'company_limit','products'=>'product_limit','customers'=>'customer_limit','users'=>'user_limit'];$usage=[];foreach($map as $table=>$limit){$actual=$table==='customers'?'retailers':$table;$s=$db->prepare("SELECT COUNT(*) FROM {$actual} WHERE tenant_id=:tenant");$s->execute([':tenant'=>$tenant]);$usage[$table]=[(int)$s->fetchColumn(),$sub[$limit]];}$pay=$db->prepare('SELECT * FROM subscription_payments WHERE tenant_id=:tenant ORDER BY id DESC');$pay->execute([':tenant'=>$tenant]);$payments=$pay->fetchAll();$days=$sub['ends_at']?max(0,(int)((strtotime($sub['ends_at'])-strtotime(date('Y-m-d')))/86400)):null;
?><div class="page-header-container"><div><h2 class="page-title">My Subscription</h2><div class="page-subtitle">Plan, usage, renewal status and payment history.</div></div></div><?php if(!in_array($sub['status'],['trial','active','grace_period'],true)||($days!==null&&$days<=7)):?><div class="alert alert-warning">Your subscription is <?=htmlspecialchars($sub['status'])?><?=($days!==null)?"; {$days} day(s) remain":''?>. New records are restricted after expiry, but your historical data remains safe.</div><?php endif?><div class="row g-3"><div class="col-lg-4"><div class="dark-card h-100"><h4><?=htmlspecialchars($sub['plan_name'])?></h4><p class="text-secondary">Status: <strong><?=htmlspecialchars($sub['status'])?></strong></p><p>Start: <?=formatDate($sub['starts_at'])?><br>Expiry: <?=formatDate($sub['ends_at'])?></p></div></div><div class="col-lg-8"><div class="dark-card h-100"><h5>Usage and limits</h5><div class="row g-3"><?php foreach($usage as $label=>$u):?><div class="col-6"><div class="p-3 border rounded"><strong><?=ucfirst($label)?></strong><br><span class="fs-4"><?=$u[0]?></span> / <?=$u[1]??'∞'?></div></div><?php endforeach?></div></div></div></div><div class="dark-card mt-4"><h5>Payment history</h5><div class="table-responsive"><table class="dark-table"><thead><tr><th>Date</th><th>Method</th><th>Reference</th><th>Amount</th><th>Status</th></tr></thead><tbody><?php foreach($payments as $p):?><tr><td><?=formatDate($p['payment_date'])?></td><td><?=htmlspecialchars($p['payment_method'])?></td><td><?=htmlspecialchars($p['transaction_reference']??'—')?></td><td><?=formatBDT($p['amount'])?></td><td><?=htmlspecialchars($p['status'])?></td></tr><?php endforeach?></tbody></table></div></div><?php require_once __DIR__.'/../../includes/footer.php';?>
